insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Poderão ser ministrados ao condenado, durante o tempo de permanência, cursos e palestras, ou atribuídas atividades educativas. Nos casos de violência doméstica e familiar contra a criança, o adolescente e a mulher e de tratamento cruel ou degradante, ou de uso de formas violentas de educação, correção ou disciplina contra a criança e o adolescente, o juiz poderá determinar o comparecimento obrigatório do agressor a programas de recuperação e reeducação.', '["Cursos, palestras e atividades educativas.","Comparecimento obrigatório do agressor a programas de reeducação."]'::jsonb, '["ATUALIZAÇÃO: o parágrafo único foi ampliado por lei posterior (violência contra criança, adolescente e mulher)."]'::jsonb, 'O juiz determina que o agressor frequente programa de reeducação.', '["Assertiva que restringe o programa de reeducação aos casos de violência contra a mulher erra: abrange crianças e adolescentes."]'::jsonb, '[]'::jsonb, '["Lei Maria da Penha"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-152' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '95d0fc37f78693550c5919e2856253c4f7e44b06c78686b522861447534fe1ee'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O estabelecimento designado encaminhará, mensalmente, ao Juiz da execução relatório, bem assim comunicará, a qualquer tempo, a ausência ou falta disciplinar do condenado.', '["Relatório mensal.","Comunicação imediata de ausência ou falta."]'::jsonb, '["Relatório MENSAL."]'::jsonb, 'O estabelecimento envia ao juiz o relatório todo mês.', '["Assertiva que dispensa a comunicação de ausência erra."]'::jsonb, '[]'::jsonb, '["Art. 150"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-153' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c3b632e14f01feab65901b880a9d220acbdf2e63d13b575566f72a4b4d71732a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Caberá ao Juiz da execução comunicar à autoridade competente a pena aplicada, determinada a intimação do condenado. Na hipótese de pena de interdição do art. 47, inciso I, do Código Penal, a autoridade deverá, em 24 horas contadas do recebimento do ofício, baixar ato, a partir do qual a execução terá início. Nas hipóteses do art. 47, incisos II e III, o juízo determinará a apreensão dos documentos que autorizam o exercício do direito interditado.', '["Comunicação da pena à autoridade competente.","Interdição do inciso I: ato em 24 horas.","Incisos II e III: apreensão dos documentos."]'::jsonb, '["Autoridade tem 24 horas para baixar o ato."]'::jsonb, 'O juiz determina a apreensão da carteira de habilitação do condenado interditado.', '["Assertiva que fixa em 48 horas o prazo da autoridade para baixar o ato erra: são 24 horas."]'::jsonb, '[]'::jsonb, '["Código Penal, art. 47"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-154' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6a761a6ad055951fe368471e799ba48a22b936a58bf200ad18f938e52c1a13b4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade deverá comunicar imediatamente ao Juiz da execução o descumprimento da pena. A comunicação poderá ser feita por qualquer prejudicado.', '["Comunicação imediata do descumprimento.","Qualquer prejudicado pode comunicar."]'::jsonb, '["Qualquer PREJUDICADO pode comunicar."]'::jsonb, 'A pessoa prejudicada pelo descumprimento comunica diretamente ao juiz.', '["Assertiva que restringe a comunicação do descumprimento às autoridades erra: qualquer prejudicado pode fazê-la."]'::jsonb, '[]'::jsonb, '["Art. 154"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-155' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4b584ff869428961495c98f56ae30ab641a143a4b32753aeee90791c8c2a2159'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juiz poderá suspender, pelo período de 2 a 4 anos, a execução da pena privativa de liberdade, não superior a 2 anos, na forma prevista nos arts. 77 a 82 do Código Penal.', '["Suspensão condicional (sursis) por 2 a 4 anos.","Pena não superior a 2 anos."]'::jsonb, '["Sursis: 2 a 4 anos de prova, para pena de até 2 anos."]'::jsonb, 'Condenado a 1 ano e 6 meses pode ter o sursis por 2 a 4 anos.', '["Assertiva que fixa o período de prova do sursis em 1 a 3 anos erra: é de 2 a 4 anos."]'::jsonb, '[]'::jsonb, '["Código Penal, arts. 77 a 82"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-156' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c94b8fae762b47ee04a323f6ae1883f4506489df2b8a3ae23d888ea10960da56'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juiz ou Tribunal, na sentença que aplicar pena privativa de liberdade, na situação do art. 156, deverá pronunciar-se, motivadamente, sobre a suspensão condicional, quer a conceda, quer a denegue.', '["Dever de pronunciar-se sobre o sursis, concedendo ou negando."]'::jsonb, '["Manifestação motivada obrigatória."]'::jsonb, 'A sentença explica por que concedeu ou negou o sursis.', '["Assertiva que dispensa a manifestação sobre o sursis na sentença erra."]'::jsonb, '[]'::jsonb, '["Art. 156"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-157' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1e2ac7abf8bd608f36b2b7d0a2642c52fa976eb33c1499b5055a1dfc0d2392a9'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concedida a suspensão, o Juiz especificará as condições a que fica sujeito o condenado, pelo prazo fixado, começando este a correr da audiência do art. 160. As condições serão adequadas ao fato e à situação pessoal do condenado, devendo incluir prestar serviços à comunidade ou limitação de fim de semana. O Juiz poderá, a qualquer tempo, de ofício, a requerimento do MP ou mediante proposta do Conselho Penitenciário, modificar as condições, ouvido o condenado. A fiscalização é atribuída a serviço social penitenciário, Patronato, Conselho da Comunidade ou instituição beneficiada. O beneficiário comunica sua ocupação e os salários. A entidade fiscalizadora comunica imediatamente fatos que possam gerar revogação, prorrogação ou modificação. Se permitida a mudança, será feita comunicação ao Juiz e à entidade do novo local.', '["Condições adequadas ao fato e à pessoa.","Prazo corre da audiência admonitória.","Modificação das condições a qualquer tempo.","Fiscalização por entidades e comunicação de fatos relevantes."]'::jsonb, '["O prazo do sursis corre da AUDIÊNCIA admonitória."]'::jsonb, 'O prazo do sursis começa a contar na audiência em que o condenado é advertido.', '["Assertiva que inicia o prazo do sursis na data da sentença erra: é a da audiência."]'::jsonb, '[]'::jsonb, '["Art. 160"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-158' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '40db37846e6f7503780c30dda82b482064cfa2d173bcffb8030f6d7ad4836d0e'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a suspensão condicional da pena for concedida por Tribunal, a este caberá estabelecer as condições do benefício, e de igual modo se o Tribunal modificar as condições da sentença recorrida. O Tribunal poderá conferir ao Juízo da execução a incumbência de estabelecer as condições e, em qualquer caso, a de realizar a audiência admonitória.', '["Tribunal estabelece as condições do sursis que concede.","Pode delegar ao juízo da execução.","Audiência admonitória pelo juízo da execução."]'::jsonb, '["A audiência admonitória cabe ao juízo da execução."]'::jsonb, 'O tribunal concede o sursis e o juízo da execução realiza a audiência.', '["Assertiva que obriga o tribunal a realizar a audiência admonitória erra: ele pode delegá-la."]'::jsonb, '[]'::jsonb, '["Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-159' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '73c8a4740a0cec563dc78460f571b607abcdaeea967f8f0d5a68f90e4e96f3a4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitada em julgado a sentença condenatória, o Juiz a lerá ao condenado, em audiência, advertindo-o das consequências de nova infração penal e do descumprimento das condições impostas.', '["Leitura da sentença em audiência.","Advertência das consequências."]'::jsonb, '["Audiência admonitória."]'::jsonb, 'O juiz lê a sentença ao condenado e o adverte sobre as condições.', '["Assertiva que dispensa a audiência admonitória no sursis erra."]'::jsonb, '[{"termo":"Audiência admonitória","significado":"Audiência em que o condenado é advertido das condições do sursis."}]'::jsonb, '["Art. 161"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-160' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9bb63af9a00ea68d178c073b792d5558c39a4b0294969bb734330f56142e1017'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se, intimado pessoalmente ou por edital com prazo de 20 dias, o réu não comparecer injustificadamente à audiência admonitória, a suspensão ficará sem efeito e será executada imediatamente a pena.', '["Ausência injustificada: o sursis perde efeito.","Intimação pessoal ou por edital de 20 dias."]'::jsonb, '["Edital com prazo de 20 dias."]'::jsonb, 'O réu que não comparece à audiência perde o sursis e cumpre a pena.', '["Assertiva que fixa em 10 dias o prazo do edital erra: são 20 dias."]'::jsonb, '[]'::jsonb, '["Art. 160"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-161' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a2c8fd2cd9016d664d634d8e08be6934ae7642e3a8b0ed46e61483c33126dc55'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A revogação da suspensão condicional da pena e a prorrogação do período de prova dar-se-ão na forma do art. 81 e respectivos parágrafos do Código Penal.', '["Revogação e prorrogação conforme o Código Penal."]'::jsonb, '["Remissão ao art. 81 do Código Penal."]'::jsonb, 'A revogação do sursis segue o art. 81 do Código Penal.', '["Assertiva que cria regras próprias de revogação do sursis na LEP, distintas do Código Penal, erra."]'::jsonb, '[]'::jsonb, '["Código Penal, art. 81"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-162' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '549d3ea64de84f9658cb22d174bc478481a13c07c568efe5895a7ff1266b45d0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A sentença condenatória será registrada, com a nota de suspensão, em livro especial do Juízo da execução. Revogada a suspensão ou extinta a pena, será o fato averbado à margem do registro. O registro e a averbação serão sigilosos, salvo para efeito de informações requisitadas por órgão judiciário ou pelo Ministério Público, para instruir processo penal.', '["Registro em livro especial.","Averbação da revogação ou extinção.","Sigilo, salvo requisição judicial ou do MP."]'::jsonb, '["Registro SIGILOSO."]'::jsonb, 'O registro do sursis só é informado a órgãos judiciários ou ao Ministério Público.', '["Assertiva que torna público o registro do sursis erra: é sigiloso."]'::jsonb, '[]'::jsonb, '["Art. 202"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-163' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '7826f84d728840874a245b6a492a69f33121ae1128039d631ddbd78e648d0221'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Extraída certidão da sentença condenatória com trânsito em julgado, que valerá como título executivo judicial, o Ministério Público requererá, em autos apartados, a citação do condenado para, no prazo de 10 dias, pagar o valor da multa ou nomear bens à penhora. Decorrido o prazo sem pagamento, proceder-se-á à penhora de tantos bens quantos bastem. A nomeação de bens e a execução seguirão a lei processual civil.', '["Certidão da sentença como título executivo judicial.","Citação para pagar em 10 dias ou nomear bens.","Penhora e execução pela lei processual civil."]'::jsonb, '["ATUALIZAÇÃO: após a Lei 13.964, a execução da multa é feita pelo juízo da execução penal, e a legitimidade da cobrança foi objeto de decisão do STF; confira o entendimento vigente.","Prazo de 10 dias."]'::jsonb, 'O condenado é citado para pagar a multa em dez dias.', '["Assertiva que fixa em 30 dias o prazo para pagar a multa erra: são 10 dias."]'::jsonb, '[]'::jsonb, '["Art. 165"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-164' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '1cb6d215213c5dbc63a44235827d6c7988d35ce6a554a4973fd8118843a13b40'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Se a penhora recair em bem imóvel, os autos apartados serão remetidos ao Juízo Cível para prosseguimento.', '["Penhora de imóvel: autos ao Juízo Cível."]'::jsonb, '["Imóvel: Juízo Cível."]'::jsonb, 'Penhorado um imóvel, o processo vai ao Juízo Cível.', '["Assertiva que mantém a execução do imóvel no juízo da execução penal erra."]'::jsonb, '[]'::jsonb, '["Art. 164"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-165' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a047ef0b414d058713cfa2498aa072375d4d5b74664a7da359bb72a32d08064a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Recaindo a penhora em outros bens, dar-se-á prosseguimento nos termos do §2º do art. 164 da Lei.', '["Outros bens: prosseguimento pela lei processual civil."]'::jsonb, '["Remissão ao art. 164, §2º."]'::jsonb, 'A penhora de um veículo segue a lei processual civil.', '["Assertiva que manda enviar ao Juízo Cível também a penhora de bens móveis erra: apenas a de imóvel."]'::jsonb, '[]'::jsonb, '["Art. 164"]'::jsonb, 'under_review', 'claude'
