insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A execução da pena de multa será suspensa quando sobrevier ao condenado doença mental, conforme o art. 52 do Código Penal.', '["Suspensão da multa por doença mental superveniente."]'::jsonb, '["Doença mental SUPERVENIENTE."]'::jsonb, 'A cobrança da multa é suspensa se o condenado adoece mentalmente.', '["Assertiva que mantém a cobrança da multa mesmo com doença mental superveniente erra."]'::jsonb, '[]'::jsonb, '["Código Penal, art. 52"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-167' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ce52bfa7232677a70148a83b91ff593bcaf911ded52079c8ae2036d0ca228386'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
