insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Juiz poderá determinar que a cobrança da multa se efetue mediante desconto no vencimento ou salário do condenado, nas hipóteses do art. 50, §1º, do Código Penal, observando que o limite máximo do desconto mensal será o da quarta parte da remuneração e o mínimo o de um décimo; o desconto será feito mediante ordem do juiz; e o responsável pelo desconto será intimado a recolher mensalmente a importância determinada.', '["Desconto no salário.","Máximo de um quarto e mínimo de um décimo da remuneração.","Ordem do juiz e recolhimento mensal."]'::jsonb, '["Desconto entre UM DÉCIMO e UM QUARTO da remuneração."]'::jsonb, 'O juiz manda descontar um décimo do salário do condenado para pagar a multa.', '["Assertiva que permite desconto de metade do salário erra: o máximo é a quarta parte."]'::jsonb, '[]'::jsonb, '["Art. 169"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-168' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3f387d6ee42dc7d08a84974a6609212e327833080828fe97fe5ba97eecc39912'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Até o término do prazo do art. 164, poderá o condenado requerer ao Juiz o pagamento da multa em prestações mensais, iguais e sucessivas. O Juiz, antes de decidir, poderá determinar diligências para verificar a situação econômica do condenado e, ouvido o Ministério Público, fixará o número de prestações. Se o condenado for impontual ou melhorar de situação econômica, o Juiz revogará o benefício, executando-se a multa.', '["Parcelamento em prestações mensais.","Diligências sobre a situação econômica.","Revogação por impontualidade ou melhora econômica."]'::jsonb, '["Revogação do parcelamento por impontualidade ou melhora econômica."]'::jsonb, 'O condenado parcela a multa, mas perde o benefício se atrasar.', '["Assertiva que impede o parcelamento da multa erra: é possível."]'::jsonb, '[]'::jsonb, '["Art. 164"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-169' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '5e3b3adaa3b545cdee7b306ed8b3bb170c4f4ecdc549cb6024bd430bea9075bc'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quando a pena de multa for aplicada cumulativamente com pena privativa da liberdade, enquanto esta estiver sendo executada, poderá aquela ser cobrada mediante desconto na remuneração do condenado. Se o condenado cumprir a pena privativa ou obtiver livramento condicional sem haver resgatado a multa, a cobrança far-se-á nos termos do Capítulo. O mesmo se aplica à suspensão condicional da pena.', '["Multa cumulativa pode ser descontada da remuneração durante a pena.","Após o cumprimento, cobra-se pelo procedimento comum.","Vale também no sursis."]'::jsonb, '["Cobrança após o cumprimento da pena privativa, livramento ou sursis."]'::jsonb, 'A multa cumulativa é descontada do salário do preso que trabalha.', '["Assertiva que extingue a multa com o cumprimento da pena privativa erra: ela é cobrada pelo procedimento comum."]'::jsonb, '[]'::jsonb, '["Art. 168"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-170' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b6fbb849f2b6749ae9e0a775c341b1cc491ba6e6ace05e11ddaa4f16ec24c8ae'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Transitada em julgado a sentença que aplicar medida de segurança, será ordenada a expedição de guia para a execução.', '["Guia para a execução da medida de segurança."]'::jsonb, '["Trânsito em julgado."]'::jsonb, 'Transitada a sentença, o juiz manda expedir a guia da medida de segurança.', '["Assertiva que dispensa a guia na medida de segurança erra."]'::jsonb, '[]'::jsonb, '["Art. 172"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-171' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f776066501f33eaa06499c0cff4dbae727ef5d7fe969b226c0c1b846c658e2e3'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
