insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ninguém será internado em Hospital de Custódia e Tratamento Psiquiátrico, ou submetido a tratamento ambulatorial, para cumprimento de medida de segurança, sem a guia expedida pela autoridade judiciária.', '["Sem guia, sem internação ou tratamento ambulatorial."]'::jsonb, '["Guia judicial obrigatória."]'::jsonb, 'O HCTP só interna com a guia judicial.', '["Assertiva que permite a internação sem guia judicial erra."]'::jsonb, '[]'::jsonb, '["Art. 171"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-172' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '867f0b30f71fc8e8973f42d0599edbf75c87755844877e829712e2243afaedd1'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A guia de internamento ou de tratamento ambulatorial, extraída pelo escrivão, que a rubricará em todas as folhas e a subscreverá com o Juiz, será remetida à autoridade administrativa incumbida da execução e conterá a qualificação do agente e o registro geral; o inteiro teor da denúncia e da sentença e a certidão de trânsito; a data em que terminará o prazo mínimo de internação ou de tratamento ambulatorial; e outras peças. Ao Ministério Público será dada ciência, e a guia será retificada sempre que sobrevierem modificações quanto ao prazo.', '["Conteúdo da guia de internamento.","Data final do prazo mínimo.","Ciência ao Ministério Público.","Retificação por mudança de prazo."]'::jsonb, '["Indica a data de término do PRAZO MÍNIMO."]'::jsonb, 'A guia informa quando termina o prazo mínimo de internação.', '["Assertiva que fixa na guia a data final definitiva da medida de segurança erra: indica o prazo mínimo."]'::jsonb, '[]'::jsonb, '["Art. 175"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-173' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ff9b627f962be89ff2cf27852ecdf9035e250d166ca7b38b8c2e7e3902f8dbca'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
