insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Aplicar-se-á, na execução da medida de segurança, naquilo que couber, o disposto nos arts. 8º e 9º da Lei, que tratam do exame criminológico e dos exames da Comissão.', '["Aplicação dos arts. 8º e 9º à medida de segurança."]'::jsonb, '["Exames aplicados no que couber."]'::jsonb, 'A execução da medida de segurança também prevê exames técnicos.', '["Assertiva que afasta os exames dos arts. 8º e 9º da medida de segurança erra."]'::jsonb, '[]'::jsonb, '["Arts. 8º e 9º"]'::jsonb, 'under_review', 'claude'
