and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A cessação da periculosidade será averiguada no fim do prazo mínimo de duração da medida de segurança, pelo exame das condições pessoais do agente. A autoridade administrativa, até 1 mês antes de expirar o prazo mínimo, remeterá ao Juiz minucioso relatório, instruído com laudo psiquiátrico. Serão ouvidos, sucessivamente, o Ministério Público e o curador ou defensor, no prazo de 3 dias para cada um. O Juiz nomeará curador ou defensor para quem não o tiver, poderá determinar novas diligências e proferirá sua decisão no prazo de 5 dias.', '["Averiguação da cessação da periculosidade no fim do prazo mínimo.","Relatório até 1 mês antes, com laudo psiquiátrico.","Oitiva do MP e do curador ou defensor em 3 dias cada.","Decisão em 5 dias."]'::jsonb, '["Relatório 1 mês antes; manifestações em 3 dias; decisão em 5 dias."]'::jsonb, 'Um mês antes do fim do prazo mínimo, a unidade envia o relatório ao juiz.', '["Assertiva que fixa em 10 dias o prazo de decisão do juiz erra: são 5 dias."]'::jsonb, '[]'::jsonb, '["Art. 176"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-175' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f12d56bfbaabe505a14c25ae7bdefe2f2d6bd411f001f7d8c10d2b007430eaa5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
