insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Em qualquer tempo, ainda no decorrer do prazo mínimo de duração da medida de segurança, poderá o Juiz da execução, diante de requerimento fundamentado do Ministério Público ou do interessado, seu procurador ou defensor, ordenar o exame para que se verifique a cessação da periculosidade, procedendo-se nos termos do artigo anterior.', '["Exame de cessação a qualquer tempo, a requerimento fundamentado."]'::jsonb, '["Possível mesmo antes do fim do prazo mínimo."]'::jsonb, 'O defensor requer o exame antes do fim do prazo mínimo.', '["Assertiva que só admite o exame de cessação ao final do prazo mínimo erra."]'::jsonb, '[]'::jsonb, '["Art. 175"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-176' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6a7554eac4669f2cc88835b610e1808994b89409a0cfd9beb084c774f7100bee'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
