insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nas hipóteses de desinternação ou de liberação, conforme o art. 97, §3º, do Código Penal, aplicar-se-á o disposto nos arts. 132 e 133 da Lei, que tratam das condições do livramento condicional.', '["Desinternação ou liberação seguem os arts. 132 e 133."]'::jsonb, '["Mesmas condições do livramento."]'::jsonb, 'O desinternado fica sujeito a condições semelhantes às do livramento condicional.', '["Assertiva que isenta o desinternado de qualquer condição erra."]'::jsonb, '[]'::jsonb, '["Arts. 132 e 133"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-178' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '0cfb4b277f59f40f1b4bb88422ee1b8ba434bd6d530a6cb58f91c2923440be43'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
