insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A pena restritiva de direitos será convertida em privativa de liberdade nas hipóteses e na forma do art. 45 e seus incisos do Código Penal. A prestação de serviços à comunidade será convertida quando o condenado não for encontrado ou desatender intimação por edital; não comparecer injustificadamente; recusar-se a prestar o serviço; praticar falta grave; ou sofrer condenação por outro crime à pena privativa de liberdade cuja execução não tenha sido suspensa. A limitação de fim de semana é convertida quando o condenado não comparecer ao estabelecimento, recusar-se à atividade, ou nas hipóteses de não localização, falta grave e nova condenação. A interdição temporária é convertida quando o condenado exercer, injustificadamente, o direito interditado, ou nas hipóteses de não localização e nova condenação.', '["Conversão da pena restritiva em privativa.","Hipóteses da prestação de serviços à comunidade.","Hipóteses da limitação de fim de semana.","Hipóteses da interdição temporária."]'::jsonb, '["Falta grave e nova condenação sem suspensão levam à conversão."]'::jsonb, 'Quem se recusa a prestar o serviço comunitário tem a pena convertida em privativa de liberdade.', '["Assertiva que impede a conversão da pena restritiva por falta grave erra."]'::jsonb, '[]'::jsonb, '["Art. 180"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-181' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '9f3ec63fd2c0d127330e67b3b2d8904efeb48cd7efc9fe8a8cb39c5f03c6ccc8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

