select u.id, u.content_sha256, 'O Conselho Penitenciário, à vista dos autos e do prontuário, promoverá as diligências necessárias e fará, em relatório, a narração do ilícito penal e dos fundamentos da sentença, a exposição dos antecedentes do condenado e do procedimento deste depois da prisão, emitindo seu parecer sobre o mérito do pedido.', '["Relatório do Conselho Penitenciário.","Parecer sobre o mérito."]'::jsonb, '["Relatório e parecer."]'::jsonb, 'O Conselho elabora relatório sobre o crime e a conduta do condenado.', '["Assertiva que dispensa o parecer do Conselho sobre o mérito erra."]'::jsonb, '[]'::jsonb, '["Art. 189"]'::jsonb, 'under_review', 'claude'
