select u.id, u.content_sha256, 'O procedimento correspondente às situações previstas nesta Lei será judicial, desenvolvendo-se perante o Juízo da execução.', '["Procedimento judicial perante o juízo da execução."]'::jsonb, '["Procedimento JUDICIAL."]'::jsonb, 'Os incidentes da execução tramitam no juízo da execução.', '["Assertiva que atribui os incidentes à autoridade administrativa erra: são judiciais."]'::jsonb, '[]'::jsonb, '["Art. 195"]'::jsonb, 'under_review', 'claude'
