select u.id, u.content_sha256, 'O procedimento judicial iniciar-se-á de ofício, a requerimento do Ministério Público, do interessado, de quem o represente, de seu cônjuge, parente ou descendente, mediante proposta do Conselho Penitenciário, ou, ainda, da autoridade administrativa.', '["Início de ofício ou por vários legitimados."]'::jsonb, '["Início de OFÍCIO é possível."]'::jsonb, 'O juiz inicia o procedimento de ofício.', '["Assertiva que exige sempre provocação para iniciar o procedimento erra: pode iniciar-se de ofício."]'::jsonb, '[]'::jsonb, '["Art. 194"]'::jsonb, 'under_review', 'claude'
