insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A portaria ou petição será autuada, ouvindo-se, em 3 dias, o condenado e o Ministério Público, quando não figurem como requerentes. Sendo desnecessária a produção de prova, o Juiz decidirá de plano, em igual prazo. Entendendo indispensável a prova pericial ou oral, o Juiz a ordenará, decidindo após a produção daquela ou na audiência designada.', '["Oitiva do condenado e do MP em 3 dias.","Decisão de plano, em igual prazo.","Prova pericial ou oral, se indispensável."]'::jsonb, '["Prazo de 3 dias."]'::jsonb, 'O juiz ouve o condenado e o MP em três dias e decide de plano.', '["Assertiva que fixa em 10 dias a oitiva do condenado e do MP erra: são 3 dias."]'::jsonb, '[]'::jsonb, '["Art. 197"]'::jsonb, 'under_review', 'claude'
