insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Das decisões proferidas pelo Juiz caberá recurso de agravo, sem efeito suspensivo.', '["Agravo em execução, sem efeito suspensivo."]'::jsonb, '["Agravo SEM efeito suspensivo."]'::jsonb, 'A decisão do juiz da execução é impugnada por agravo, mas continua valendo.', '["Assertiva que atribui efeito suspensivo ao agravo em execução erra."]'::jsonb, '[{"termo":"Agravo em execução","significado":"Recurso cabível contra decisões do juiz da execução."}]'::jsonb, '["Art. 196"]'::jsonb, 'under_review', 'claude'
