insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É defesa ao integrante dos órgãos da execução penal e ao servidor a divulgação de ocorrência que perturbe a segurança e a disciplina dos estabelecimentos, bem como exponha o preso à inconveniente notoriedade, durante o cumprimento da pena.', '["Vedada a divulgação de ocorrências que perturbem a segurança.","Vedada a exposição do preso à notoriedade."]'::jsonb, '["Proteção da imagem do preso."]'::jsonb, 'O servidor não pode divulgar a rebelião ou expor o preso à imprensa.', '["Assertiva que autoriza o servidor a expor o preso à imprensa erra."]'::jsonb, '[]'::jsonb, '["Art. 41, VIII"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-198' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b63ba9c4f2f67ec49601ce59ef8042abe947aff1363d4c708c65c87024c6dea5'
