select u.id, u.content_sha256, 'O condenado por crime político não está obrigado ao trabalho.', '["Condenado por crime político não é obrigado a trabalhar."]'::jsonb, '["Exceção à obrigatoriedade do trabalho."]'::jsonb, 'O condenado por crime político pode recusar o trabalho.', '["Assertiva que obriga o condenado por crime político a trabalhar erra."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
