from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-201' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd84266787e7438575d0de9962d2886e92892a806eb8c32c4fdbfcc08ef3810d8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
