insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Cumprida ou extinta a pena, não constarão da folha corrida, atestados ou certidões fornecidas por autoridade policial ou por auxiliares da Justiça qualquer notícia ou referência à condenação, salvo para instruir processo pela prática de nova infração penal ou outros casos expressos em lei.', '["Sigilo da condenação após o cumprimento ou extinção.","Exceções: nova infração penal e casos legais."]'::jsonb, '["Efeito de proteção do egresso."]'::jsonb, 'A certidão de antecedentes não menciona a condenação já cumprida.', '["Assertiva que mantém a condenação cumprida na folha corrida erra, salvo nas exceções legais."]'::jsonb, '[]'::jsonb, '["Art. 163"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-202' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '66ffa6a8cd1b14c327d1502e7ea95ac1138ad3e516b01c62dbc17feba83e1186'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
