insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No prazo de 6 meses, a contar da publicação da Lei, serão editadas as normas complementares ou regulamentares necessárias à eficácia dos dispositivos não autoaplicáveis. Dentro do mesmo prazo, as Unidades Federativas, em convênio com o Ministério da Justiça, projetarão a adaptação, construção e equipamento de estabelecimentos e serviços penais, e será providenciada a aquisição ou desapropriação de prédios para casas de albergados. O prazo poderá ser ampliado pelo Conselho Nacional, e o descumprimento injustificado implicará a suspensão de ajuda financeira da União.', '["Prazo de 6 meses para normas complementares.","Adaptação e construção de estabelecimentos.","Prorrogação pelo Conselho Nacional.","Suspensão de ajuda financeira em caso de descumprimento."]'::jsonb, '["Dispositivo transitório.","Descumprimento injustificado suspende a ajuda financeira federal."]'::jsonb, 'O Estado que não adapta seus presídios perde a ajuda financeira da União.', '["Assertiva que fixa em 1 ano o prazo do art. 203 erra: são 6 meses."]'::jsonb, '[]'::jsonb, '["Art. 204"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-203' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'eba9a07aab2c10c742f1432b76dd696bc52993ab77349389bc296efdfc4d69d5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Esta Lei entra em vigor concomitantemente com a lei de reforma da Parte Geral do Código Penal, revogadas as disposições em contrário, especialmente a Lei nº 3.274, de 2 de outubro de 1957.', '["Vigência junto com a reforma da Parte Geral do Código Penal.","Revoga a Lei nº 3.274, de 1957."]'::jsonb, '["Dispositivo histórico."]'::jsonb, 'A LEP e a reforma do Código Penal passaram a valer juntas.', '["Assertiva que prevê vigência imediata na data da publicação erra: foi concomitante com a reforma do Código Penal."]'::jsonb, '[]'::jsonb, '["Art. 203"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'lep' and u.unit_key = 'art-204' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'f2270977584c0df354430e4f321c2b22488818709b1ff0e872c36544dfc3f384'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A lei cria um sistema de proteção integral voltado a todas as crianças e adolescentes, tratando-os como sujeitos de direitos e não como meros objetos de tutela.', '["Doutrina da proteção integral.","Criança e adolescente como sujeitos de direitos."]'::jsonb, '["Proteção INTEGRAL é a ideia central do Estatuto."]'::jsonb, 'Toda política pública para a infância parte da proteção integral prevista no Estatuto.', '["Assertiva que restringe a proteção integral apenas a crianças em situação irregular erra."]'::jsonb, '[{"termo":"Proteção integral","significado":"Garantia de todos os direitos fundamentais a toda criança e adolescente."}]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-1' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '6f6f398dcac3edc432e4e9eff795dbe38f1b975c19a41c2c3fbdda3913a2f163'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Criança é quem tem até doze anos incompletos; adolescente é quem tem de doze a dezoito anos. Em casos expressos em lei, o Estatuto aplica-se, excepcionalmente, a quem tem entre dezoito e vinte e um anos.', '["Criança: até doze anos incompletos.","Adolescente: doze a dezoito anos.","Aplicação excepcional entre dezoito e vinte e um anos."]'::jsonb, '["O critério é cronológico e a idade de doze anos já é de adolescente.","A extensão até vinte e um anos só vale nos casos expressos em lei, como a medida socioeducativa."]'::jsonb, 'Quem tem doze anos completos já é adolescente para o Estatuto.', '["Assertiva que define criança como quem tem até doze anos completos erra: são doze anos incompletos."]'::jsonb, '[]'::jsonb, '["Art. 121, §5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-2' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4af441f95435480102fcffeee77e5d850ee6553135cc0952cf0e52fa1b1308e5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crianças e adolescentes têm todos os direitos fundamentais da pessoa humana, além da proteção integral, com oportunidades para se desenvolverem física, mental, moral, espiritual e socialmente em liberdade e dignidade. Esses direitos valem para todos, sem discriminação alguma.', '["Direitos fundamentais plenos.","Desenvolvimento integral em liberdade e dignidade.","Aplicação sem discriminação."]'::jsonb, '["O rol de não discriminação é amplo e inclui deficiência, etnia e condição econômica."]'::jsonb, 'Uma criança de família pobre tem os mesmos direitos de qualquer outra.', '["Assertiva que condiciona os direitos à situação familiar da criança erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-3' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c9bf227bc9e5889ab87dd5d48c93fffeb48fd4a01c0f7f558d0b0e64133b51ca'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É dever da família, da comunidade, da sociedade e do poder público garantir, com absoluta prioridade, os direitos da criança e do adolescente, como vida, saúde, educação, convivência familiar e comunitária. A prioridade compreende receber proteção e socorro em primeiro lugar, precedência de atendimento, preferência nas políticas sociais e destinação privilegiada de recursos públicos.', '["Dever de família, comunidade, sociedade e poder público.","Absoluta prioridade.","Primazia de socorro, precedência de atendimento, preferência em políticas e recursos privilegiados."]'::jsonb, '["A prioridade é ABSOLUTA e vem do texto constitucional.","O dever é compartilhado, não só do Estado."]'::jsonb, 'Em uma emergência, a criança deve ser socorrida em primeiro lugar.', '["Assertiva que atribui o dever de garantir os direitos apenas ao poder público erra."]'::jsonb, '[{"termo":"Absoluta prioridade","significado":"Preferência incondicional da criança e do adolescente em atendimento e recursos."}]'::jsonb, '["Constituição Federal, art. 227"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-4' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'b5afd2c8faedc3115483fb37abedea696fb425bad5ea6b8d501f0670fd9887a0'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nenhuma criança ou adolescente pode ser vítima de negligência, discriminação, exploração, violência, crueldade ou opressão, e qualquer atentado, por ação ou omissão, será punido na forma da lei. A conduta que ofende direito fundamental, inclusive o abandono afetivo, é ilícita e gera reparação de danos.', '["Vedação de negligência, discriminação, exploração, violência, crueldade e opressão.","Punição por ação ou omissão.","Reparação de danos, inclusive por abandono afetivo."]'::jsonb, '["ATUALIZAÇÃO: o parágrafo único, que inclui o abandono afetivo, foi acrescentado por lei posterior.","A omissão também é punida."]'::jsonb, 'O pai que abandona afetivamente o filho pode ser obrigado a reparar danos.', '["Assertiva que isenta de reparação o abandono afetivo erra: ele está expressamente incluído."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-5' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'ad9cc78036fea85207bdfd0aef71104c4d4356380ced38c7069a26ba0e97d89a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Na interpretação do Estatuto, deve-se levar em conta os fins sociais da lei, as exigências do bem comum, os direitos e deveres individuais e coletivos e a condição peculiar da criança e do adolescente como pessoas em desenvolvimento.', '["Interpretação teleológica.","Condição peculiar de pessoa em desenvolvimento."]'::jsonb, '["A condição de pessoa em desenvolvimento orienta toda a interpretação."]'::jsonb, 'O juiz decide considerando que o adolescente ainda está se desenvolvendo.', '["Assertiva que manda interpretar o Estatuto apenas pela letra da lei erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-6' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'de859fff91a67bd3ffe58f4c53fcc62af4af3fe8578e5f2204ac57ce88f59106'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito à proteção da vida e da saúde por meio de políticas sociais públicas que permitam o nascimento e o desenvolvimento sadio e harmonioso, em condições dignas de existência.', '["Direito à vida e à saúde.","Políticas sociais públicas.","Desenvolvimento sadio e harmonioso."]'::jsonb, '["Efetivação por políticas públicas, não só por assistência individual."]'::jsonb, 'Programas de pré-natal e vacinação concretizam esse direito.', '["Assertiva que afasta o dever de políticas públicas para a saúde infantil erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-7' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd2aac44cda21a77344d00b0fb792a51573a4989b128b2b6599af99f8367a07ce'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurado a todas as mulheres o acesso aos programas e políticas de saúde da mulher e de planejamento reprodutivo e, às gestantes, nutrição adequada, atenção humanizada à gravidez, ao parto e ao puerpério e atendimento pré-natal, perinatal e pós-natal integral no Sistema Único de Saúde. O pré-natal é feito por profissionais da atenção primária, e a gestante tem direito de opção quanto ao estabelecimento do parto.', '["Acesso a políticas de saúde da mulher e planejamento reprodutivo.","Atendimento pré-natal, perinatal e pós-natal no SUS.","Direito de opção da mulher quanto ao local do parto."]'::jsonb, '["ATUALIZAÇÃO: o artigo foi ampliado por leis posteriores sobre parto humanizado e atendimento à gestante."]'::jsonb, 'A gestante vinculada a uma maternidade pode, ainda assim, exercer o direito de opção.', '["Assertiva que restringe o atendimento pré-natal à rede particular erra: é assegurado no SUS."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-8' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'cc0ead449edfabf7c029abecddc5ac49f59a7d14207d96744415cec18201b8fb'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica instituída a Semana Nacional de Prevenção da Gravidez na Adolescência, realizada anualmente na semana que incluir o dia primeiro de fevereiro, para disseminar informações preventivas e educativas. As ações ficam a cargo do poder público, com organizações da sociedade civil, dirigidas prioritariamente aos adolescentes.', '["Semana Nacional de Prevenção da Gravidez na Adolescência.","Semana que inclui o dia primeiro de fevereiro.","Público prioritário: adolescentes."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Realizada anualmente na semana que incluir o dia primeiro de fevereiro."]'::jsonb, 'Escolas promovem palestras sobre prevenção na semana de fevereiro.', '["Assertiva que fixa a semana em dezembro erra: é a que inclui o dia primeiro de fevereiro."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-8-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c7b8b3171269c564f871c0117620ef4bdead8b4f51a1c094a7c7313cf9278377'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O poder público, as instituições e os empregadores devem propiciar condições adequadas ao aleitamento materno, inclusive para filhos de mães privadas de liberdade. Unidades de saúde desenvolvem ações sistemáticas de promoção e apoio, e as unidades de terapia intensiva neonatal devem ter banco ou unidade de coleta de leite humano.', '["Aleitamento materno protegido, inclusive no cárcere.","Ações sistemáticas nas unidades primárias de saúde.","Banco ou coleta de leite humano nas UTIs neonatais."]'::jsonb, '["A proteção alcança filhos de mães presas."]'::jsonb, 'A mãe presa deve ter condições para amamentar.', '["Assertiva que exclui as mães privadas de liberdade do direito ao aleitamento erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-9' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'bd95cee14d0dd72cd65f6ffdd02facf19b88b580bffabdb6882e2f26d02f6a9d'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Hospitais e estabelecimentos de atenção à saúde de gestantes, públicos e particulares, têm obrigações como manter prontuários individuais por dezoito anos, identificar o recém-nascido por impressão plantar e digital, e da mãe, fazer exames de metabolismo do recém-nascido e orientar os pais, fornecer declaração de nascimento e manter alojamento conjunto.', '["Prontuários por dezoito anos.","Identificação do recém-nascido e da mãe.","Exames de metabolismo e orientação aos pais.","Declaração de nascimento e alojamento conjunto."]'::jsonb, '["Prazo de guarda do prontuário: dezoito anos.","Obrigações valem para hospitais públicos e particulares."]'::jsonb, 'A maternidade colhe a impressão plantar do bebê e a digital da mãe.', '["Assertiva que fixa em cinco anos a guarda dos prontuários erra: são dezoito anos."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-10' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '17fecd732611d8dd836d17e3b885e042c8a07b072ea22c07aded73b03db7bbab'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurado acesso integral às linhas de cuidado voltadas à saúde da criança e do adolescente pelo SUS, com equidade. A criança e o adolescente com deficiência são atendidos sem discriminação ou segregação, e o poder público fornece gratuitamente medicamentos, órteses, próteses e outras tecnologias assistivas a quem precisar.', '["Acesso integral e equitativo pelo SUS.","Atendimento sem segregação de quem tem deficiência.","Fornecimento gratuito de medicamentos e tecnologias assistivas."]'::jsonb, '["Fornecimento gratuito de medicamentos, órteses e próteses."]'::jsonb, 'A criança com deficiência recebe a prótese gratuitamente pelo SUS.', '["Assertiva que condiciona o fornecimento de medicamentos à renda da família erra."]'::jsonb, '[]'::jsonb, '["Art. 7º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-11' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3317b249a3cc23f6fcdfd066bff75728c03fa04766c280e61f0ed85648140d73'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É assegurado acesso a programas de saúde mental do SUS para prevenção e tratamento de agravos, com atenção psicossocial básica e especializada, de urgência e emergência e hospitalar. Os profissionais recebem formação específica e permanente para detectar sinais de risco.', '["Programas de saúde mental no SUS.","Atenção básica, especializada, de urgência e hospitalar.","Formação específica e permanente dos profissionais."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior."]'::jsonb, 'O adolescente com sinais de depressão tem direito a acompanhamento psicossocial no SUS.', '["Assertiva que exclui a saúde mental dos programas do SUS para crianças erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-11-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '14cfba2a8596eea5fd93594951b7bacc9c2d802e14d3e9cfdb26c2d933eb106c'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Os estabelecimentos de atendimento à saúde devem permitir a permanência em tempo integral de um dos pais ou do responsável nos casos de internação da criança ou do adolescente. A criança e o adolescente também têm direito de visitar a mãe ou o pai internados.', '["Permanência integral de um dos pais na internação.","Direito de visitar o pai ou a mãe internados."]'::jsonb, '["Vale inclusive em unidades neonatais e de terapia intensiva."]'::jsonb, 'A mãe acompanha o filho internado na UTI neonatal.', '["Assertiva que limita a permanência dos pais ao horário de visitas erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-12' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '4e346845d1dcd7405d245ecb94b6ee9ea8e940dadcf6f6e13ffb32d37e08f724'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Casos de suspeita ou confirmação de castigo físico, tratamento cruel ou degradante e maus-tratos devem ser obrigatoriamente comunicados ao Conselho Tutelar, sem prejuízo de outras providências. Gestantes ou mães que queiram entregar o filho à adoção são encaminhadas, sem constrangimento, à Justiça da Infância e da Juventude, e os serviços de saúde e assistência devem acompanhar e orientar essas situações.', '["Comunicação obrigatória ao Conselho Tutelar.","Entrega voluntária para adoção sem constrangimento.","Encaminhamento à Justiça da Infância e da Juventude."]'::jsonb, '["ATUALIZAÇÃO: os parágrafos sobre entrega para adoção vieram da Lei de Adoção.","A comunicação é OBRIGATÓRIA, mesmo na suspeita."]'::jsonb, 'O médico que suspeita de maus-tratos comunica ao Conselho Tutelar.', '["Assertiva que torna facultativa a comunicação de suspeita de maus-tratos erra."]'::jsonb, '[]'::jsonb, '["Art. 245"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-13' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'a4c463e9adff8483a22491ae22268b3bb705481f36959e3b7fb9abc4400f44f4'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O SUS promove programas de assistência médica e odontológica para prevenir doenças que afetam a população infantil e campanhas de educação sanitária. A vacinação das crianças nos casos recomendados pelas autoridades sanitárias é obrigatória, e a atenção à saúde bucal é transversal, integral e intersetorial.', '["Prevenção médica e odontológica.","Vacinação obrigatória nos casos recomendados.","Atenção à saúde bucal de crianças e gestantes."]'::jsonb, '["A vacinação recomendada é OBRIGATÓRIA."]'::jsonb, 'Os pais devem vacinar a criança conforme o calendário das autoridades sanitárias.', '["Assertiva que torna facultativa a vacinação recomendada erra."]'::jsonb, '[]'::jsonb, '["Art. 249"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-14' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '60d3543a42058f4aec6f8cfd7849ea48283cfac5c36b3647a59e7342c30eefbe'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incumbe ao poder público proporcionar assistência integral e multiprofissional à criança e ao adolescente dependentes químicos ou com problemas decorrentes do uso de drogas, protegendo sua saúde física e mental e seu bem-estar social, e promover campanhas de prevenção do uso de drogas lícitas e ilícitas.', '["Assistência integral e multiprofissional.","Campanhas de prevenção de drogas lícitas e ilícitas."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior.","Abrange drogas lícitas e ilícitas."]'::jsonb, 'O município oferece tratamento multiprofissional ao adolescente dependente.', '["Assertiva que limita as campanhas às drogas ilícitas erra."]'::jsonb, '[]'::jsonb, '["Art. 11"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-14-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'c02e387e4baefcc7457d31b449719a644b043fb58f41e162bb9f63e67e73c606'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito à liberdade, ao respeito e à dignidade como pessoas humanas em processo de desenvolvimento e como sujeitos de direitos civis, humanos e sociais garantidos na Constituição e nas leis.', '["Liberdade, respeito e dignidade.","Sujeitos de direitos civis, humanos e sociais."]'::jsonb, '["Pessoas em PROCESSO DE DESENVOLVIMENTO."]'::jsonb, 'O adolescente tem o direito de ser ouvido nas decisões que o afetam.', '["Assertiva que trata a criança como objeto de direitos erra: é sujeito de direitos."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-15' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'e107ca012cdfa100d844b865200ea47cf93b5ec944aac2f24af538257b381848'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O direito à liberdade compreende ir, vir e estar nos logradouros públicos e espaços comunitários, ressalvadas as restrições legais; opinião e expressão; crença e culto religioso; brincar, praticar esportes e divertir-se; participar da vida familiar e comunitária sem discriminação; participar da vida política na forma da lei; e buscar refúgio, auxílio e orientação.', '["Sete aspectos da liberdade.","Locomoção, opinião, crença, lazer, convivência, vida política e busca de auxílio."]'::jsonb, '["São sete incisos."]'::jsonb, 'O adolescente pode frequentar a praça, ressalvadas as restrições legais.', '["Assertiva que exclui a participação na vida política dos aspectos da liberdade erra: está no inciso VI."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-16' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '30abb48133295fe01f36f2194167c7c0ef51c20d4f7541fd7d02da227575c519'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O direito ao respeito é a inviolabilidade da integridade física, psíquica e moral da criança e do adolescente, abrangendo a preservação da imagem, da identidade, da autonomia, dos valores, ideias e crenças, dos espaços e objetos pessoais.', '["Integridade física, psíquica e moral.","Imagem, identidade, autonomia, valores, espaços e objetos pessoais."]'::jsonb, '["Inclui a preservação da imagem e dos objetos pessoais."]'::jsonb, 'Divulgar a foto da criança sem proteção viola o direito ao respeito.', '["Assertiva que limita o respeito à integridade física erra: abrange também a psíquica e a moral."]'::jsonb, '[]'::jsonb, '["Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-17' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '86e05c96a5077f61d8eaceb8ed007ccb7c03c68a87e1b0a82a6faf4ea490cccd'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É dever de todos velar pela dignidade da criança e do adolescente, protegendo-os de qualquer tratamento desumano, violento, aterrorizante, vexatório ou constrangedor.', '["Dever de todos.","Proteção contra tratamento desumano, violento, aterrorizante, vexatório ou constrangedor."]'::jsonb, '["O dever é de TODOS, não só da família."]'::jsonb, 'Qualquer pessoa deve intervir diante de humilhação pública de uma criança.', '["Assertiva que restringe o dever à família erra."]'::jsonb, '[]'::jsonb, '["Art. 18-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-18' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '22c2577788e24ba7cd9d7ee4f9117d6ec1040b0320d2959d159e8299c6efab16'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito de ser educados e cuidados sem castigo físico ou tratamento cruel ou degradante, seja qual for o pretexto, pelos pais, familiares, responsáveis, agentes públicos executores de medidas socioeducativas ou qualquer pessoa encarregada de cuidar deles. Castigo físico é a ação disciplinar ou punitiva com uso da força que cause sofrimento físico ou lesão; tratamento cruel ou degradante é a conduta que humilha, ameaça gravemente ou ridiculariza.', '["Proibição de castigo físico e tratamento cruel ou degradante.","Alcança pais, familiares, responsáveis e agentes públicos.","Definições de castigo físico e de tratamento cruel."]'::jsonb, '["ATUALIZAÇÃO: a chamada Lei Menino Bernardo incluiu este artigo.","Não importa o pretexto: correção, disciplina ou educação."]'::jsonb, 'A palmada como forma de disciplina é castigo físico vedado.', '["Assertiva que admite o castigo moderado como método educativo erra."]'::jsonb, '[{"termo":"Castigo físico","significado":"Ação punitiva com força física que cause sofrimento ou lesão."}]'::jsonb, '["Art. 18-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-18-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '150b1bd405cabfb3e7012cb7b05d05396c2023142763d629b6928c05944f111a'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Quem usar castigo físico ou tratamento cruel ou degradante como forma de correção sujeita-se, sem prejuízo de outras sanções, a medidas aplicadas conforme a gravidade do caso: encaminhamento a programa de proteção à família, a tratamento psicológico ou psiquiátrico, a cursos ou programas de orientação, obrigação de encaminhar a criança a tratamento especializado e advertência. As medidas são aplicadas pelo Conselho Tutelar, sem prejuízo de outras providências legais.', '["Medidas aplicáveis ao agressor.","Gradação conforme a gravidade.","Aplicação pelo Conselho Tutelar."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído pela Lei Menino Bernardo.","As medidas não excluem outras sanções."]'::jsonb, 'O pai que bate no filho é encaminhado a programa de orientação.', '["Assertiva que exclui as medidas se houver outra sanção aplicável erra: elas valem sem prejuízo de outras sanções."]'::jsonb, '[]'::jsonb, '["Art. 18-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-18-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '3e30473c76c6197220ecbd10fe6cd3ce01c8bbdbe6832a45cafb931aa90c0dc5'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente têm direito de ser criados e educados no seio da família e, excepcionalmente, em família substituta, assegurada a convivência familiar e comunitária. Quem está em acolhimento familiar ou institucional tem sua situação reavaliada, no máximo, a cada três meses, e a permanência em acolhimento não se prolonga por mais de dezoito meses, salvo comprovada necessidade que atenda ao seu interesse superior, decidida de forma fundamentada pela autoridade judiciária.', '["Criação no seio da família, excepcionalmente em família substituta.","Reavaliação a cada três meses.","Permanência máxima de dezoito meses, salvo necessidade fundamentada."]'::jsonb, '["ATUALIZAÇÃO: reavaliação a cada três meses e limite de dezoito meses vieram da Lei de Adoção.","Acolhimento é medida provisória e excepcional."]'::jsonb, 'A situação da criança acolhida é revista a cada três meses pelo juiz.', '["Assertiva que fixa em seis meses a reavaliação do acolhimento erra: é a cada três meses."]'::jsonb, '[]'::jsonb, '["Art. 101"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-19' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '60688d53b9dd262f42ca537e4948d3d0b3e4a4ed0c5d0b4178b8521c1574c624'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A gestante ou mãe que manifeste interesse em entregar o filho para adoção, antes ou logo após o nascimento, será encaminhada à Justiça da Infância e da Juventude, onde é ouvida pela equipe interprofissional, que apresenta relatório ao juiz. O juiz pode encaminhá-la, com seu consentimento, à rede de saúde e assistência social para atendimento especializado.', '["Encaminhamento à Justiça da Infância e da Juventude.","Oitiva pela equipe interprofissional.","Atendimento especializado com consentimento."]'::jsonb, '["ATUALIZAÇÃO: artigo incluído por lei posterior sobre entrega voluntária.","A mãe não pode ser constrangida."]'::jsonb, 'A gestante que não pretende ficar com o bebê procura a Vara da Infância.', '["Assertiva que obriga a mãe a manter o filho após ouvida erra."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-19-a' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = '8beed1bb5c0f3b4f4ac079a92b273b6538788e7f09d556445a4b440c2abf5fc8'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A criança e o adolescente em acolhimento institucional ou familiar podem participar de programa de apadrinhamento, que cria vínculos externos à instituição para convivência familiar e comunitária e colaboração com seu desenvolvimento. Podem ser padrinhos pessoas maiores de dezoito anos não inscritas nos cadastros de adoção, e pessoas jurídicas podem apadrinhar para colaboração financeira, sem vínculo de guarda.', '["Apadrinhamento de crianças acolhidas.","Padrinhos maiores de dezoito anos não inscritos em cadastro de adoção.","Pessoas jurídicas podem colaborar financeiramente."]'::jsonb, '["Apadrinhamento NÃO é adoção nem guarda."]'::jsonb, 'Um casal acompanha uma criança acolhida aos finais de semana sem adotá-la.', '["Assertiva que exige a inscrição dos padrinhos no cadastro de adoção erra."]'::jsonb, '[]'::jsonb, '["Art. 19"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'eca' and u.unit_key = 'art-19-b' and u.content_status = 'current' and c.status = 'active' and u.content_sha256 = 'd8633608e6199caebda244590f1e4f0968abb72a82f03b8de7e614484c0f0582'
and exists (select 1 from public.syllabus_topics t join public.syllabus_editions d on d.id=t.edition_id where t.id=c.syllabus_topic_id and t.content_status='current' and d.status='active')
and exists (select 1 from public.content_sources s where s.url=c.source_url and s.is_official and s.status='vigente')
